INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35111, 'Acts 18:10', 'Acts', 18, 10, 'ځکه چې زه درسره مل یم او هېڅوک به ونه شي کولای چې په تا باندې حمله وکړي او زیان درته ورسوي، ځکه چې په دې ښار کې ډېر داسې خلک شته چې زما دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_10.mp3', '', 1761754199, 1761754199),
(35112, 'Acts 18:11', 'Acts', 18, 11, 'نو پولوس د یو کال او شپږو میاشتو دپاره هلته پاتې شو او خلکو ته یې د خدای د کلام تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_11.mp3', '', 1761754199, 1761754199),
(35113, 'Acts 18:12', 'Acts', 18, 12, 'خو کله چې ګالیون د جنوبي یونان د اخیې د ولایت والي وټاکل شو، نو یهودیان سره راټول شول او پولوس یې ونیوه او محکمې ته یې راوست', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_12.mp3', '', 1761754199, 1761754199),
(35114, 'Acts 18:13', 'Acts', 18, 13, 'او ویې ویل: «دا سړی خلک په داسې ډول د خدای عبادت ته هڅوي چې د قانون خلاف دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_13.mp3', '', 1761754199, 1761754199),
(35115, 'Acts 18:14', 'Acts', 18, 14, 'څنګه چې پولوس خبرې پیل کړلې، نو ګالیون یهودیانو ته وویل: «ای یهودیانو، که چېرې په دې خبره کې کومه غلطي او یا کوم سخت جرم وای چې هغه کړی وي، نو ما به ستاسو دعوه اورېدلې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_14.mp3', '', 1761754199, 1761754199),
(35116, 'Acts 18:15', 'Acts', 18, 15, 'خو څرنګه چې دا ستاسو د بحثونو موضوع، اصطلاحګانو او ستاسو د خپل شریعت خبره ده، نو تاسو خپله یې باید حل کړئ. زه نه غواړم چې د دې شیانو په هکله قضاوت وکړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_15.mp3', '', 1761754199, 1761754199),
(35117, 'Acts 18:16', 'Acts', 18, 16, 'نو هغوی یې له محکمې څخه وویستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_16.mp3', '', 1761754199, 1761754199),
(35118, 'Acts 18:17', 'Acts', 18, 17, 'خلکو سوستینیس چې د کنیسې مشر ؤ، راونیوه او د محکمې په مخکې یې وواهه. خو ګالیون یې کومه پروا ونه کړه. پولوس د قرنتوس څخه د سوریې انطاکیې ته سفر کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_17.mp3', '', 1761754199, 1761754199),
(35119, 'Acts 18:18', 'Acts', 18, 18, 'پولوس د څه وخت دپاره د ایماندارانو سره په قرنتوس کې پاتې شو او بیا یې د هغوی سره خدای پاماني وکړه او په کشتۍ کې د پریسکیلا او اکیلا سره سوریې ته لاړ. د کينخریې په ښار کې هغه خپل سر وخرایه، ځکه چې نذر یې ایښی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_18.mp3', '', 1761754199, 1761754199),
(35120, 'Acts 18:19', 'Acts', 18, 19, 'کله چې هغوی افسیس ته ورسېدل، نو پولوس پرسکیلا او اکیلا هلته پرېښودل. بیا یوازې کنیسې ته لاړ او هلته یې د یهودیانو سره بحث وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_19.mp3', '', 1761754199, 1761754199),
(35121, 'Acts 18:20', 'Acts', 18, 20, 'هغوی ورڅخه وغوښتل چې د ډېر وخت دپاره پاتې شي، خو هغه ونه منله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_20.mp3', '', 1761754199, 1761754199),
(35122, 'Acts 18:21', 'Acts', 18, 21, 'نو د هغوی سره یې خدای پاماني وکړه او ویې ویل: «که د خدای رضا وي، نو بېرته به راشم.» نو هغه د افسیس څخه په کشتۍ کې روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_21.mp3', '', 1761754199, 1761754199),
(35123, 'Acts 18:22', 'Acts', 18, 22, 'کله چې هغه په قیصریه کې د کشتۍ څخه راښکته شو، نو اورشلیم ته لاړ او د کلیسا د خلکو سره د سلام او احوال اخیستنې څخه وروسته انطاکیې ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_22.mp3', '', 1761754199, 1761754199),
(35124, 'Acts 18:23', 'Acts', 18, 23, 'په انطاکیه کې د څه مودې تېرولو څخه وروسته پولوس بیا په سفر روان شو او د غلاتیې او فریجیې په ټوله سیمه کې یې د یو ځای څخه بل ځای ته سفر کاوه او د ټولو ایماندارانو زړونه یې غښتلي کول. اپولوس په افسیس او قرنتوس کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_23.mp3', '', 1761754199, 1761754199),
(35125, 'Acts 18:24', 'Acts', 18, 24, 'په دې وخت کې یو یهودي چې اپولوس نومېده او په اصل کې د سکندریې څخه ؤ، افسیس ته راغی. هغه یو ښه ویاند ؤ او د خدای په کلام ډېر ښه پوهېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_24.mp3', '', 1761754199, 1761754199),
(35126, 'Acts 18:25', 'Acts', 18, 25, 'هغه ته د څښتن د لارې تعلیم ورکړل شوی ؤ او په زیات شور او شوق سره یې خبرې کولې او په سمه توګه یې د عیسی په هکله تعلیم ورکاوه، که څه هم هغه یوازې د یحیی د تعمید د غسل څخه خبر ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_25.mp3', '', 1761754199, 1761754199),
(35127, 'Acts 18:26', 'Acts', 18, 26, 'هغه په کنیسه کې په زړورتیا سره خبرې پیل کړې. کله چې پریسکیلا او اکیلا د هغه خبرې واورېدلې، نو هغه یې ګوښه کړ او په سمه توګه یې ورته د خدای لاره بیان کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_26.mp3', '', 1761754199, 1761754199),
(35128, 'Acts 18:27', 'Acts', 18, 27, 'اپولوس جنوبي یونان ته د تګ په هکله فکر کاوه، نو د افسیس ایماندارانو هغه وهڅاوه چې لاړ شي. هغوی د اخیې ایماندارانو ته لیک ولېږه چې هغه ته تود هرکلی ووایي. کله چې هغه هلته ورسېده، نو د هغو خلکو سره یې ډېره مرسته وکړه چې د خدای په فضل سره یې ایمان راوړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_27.mp3', '', 1761754199, 1761754199),
(35129, 'Acts 18:28', 'Acts', 18, 28, 'هغه د یهودیانو سره سخت بحث وکړ او د خلکو په مخکې یې د خدای د کلام څخه دا ثابته کړه چې عیسی هماغه مسیح دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_28.mp3', '', 1761754199, 1761754199),
(35130, 'Galatians 1:1', 'Galatians', 1, 1, 'دا لیک د پولوس رسول له خوا چې هغه نه د انسان له خوا ټاکل شوی او نه د انسان له خوا رالېږل شوی بلکې د عیسی مسیح او پلار خدای له خوا چې عیسی یې له مړو نه راژوندی کړ، رسول ټاکل شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_1.mp3', '', 1761754199, 1761754199),
(35131, 'Galatians 1:2', 'Galatians', 1, 2, 'ټول ایمانداران چې دلته زما سره دي د غلاتیې ټولو کلیساګانو ته سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_2.mp3', '', 1761754199, 1761754199),
(35132, 'Galatians 1:3', 'Galatians', 1, 3, 'زمونږ د پلار خدای او څښتن عیسی مسیح فضل او سلامتي دې وي په تاسو باندې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_3.mp3', '', 1761754199, 1761754199),
(35133, 'Galatians 1:4', 'Galatians', 1, 4, 'هغه عیسی چې خپل ژوند یې زمونږ د ګناهونو په خاطر قربان کړ، ترڅو د خدای یعنې زمونږ د اسماني پلار د ارادې سره سم مونږ د دې اوسنۍ بدکارې زمانې څخه خلاص کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_4.mp3', '', 1761754199, 1761754199),
(35134, 'Galatians 1:5', 'Galatians', 1, 5, 'د خدای جلال دې تل ترتله وي. امین. یوازې یو زېری دی بل نشته', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_5.mp3', '', 1761754199, 1761754199),
(35135, 'Galatians 1:6', 'Galatians', 1, 6, 'زه په دې ډېر حیران یم چې تاسو دومره زر د هغه چا نه مخ اړوئ چې د مسیح په فضل یې رابللي یئ او بل زېری منئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_6.mp3', '', 1761754199, 1761754199),
(35136, 'Galatians 1:7', 'Galatians', 1, 7, 'حال دا چې بل زېری نشته. خو ځینې خلک شته چې غواړي ستاسو فکرونه ګډوډ او د مسیح زېری بدل کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_7.mp3', '', 1761754199, 1761754199),
(35137, 'Galatians 1:8', 'Galatians', 1, 8, 'خو که مونږ یا حتی د اسمان یوه فرښته بې له هغه زېري څخه چې مونږ تاسو ته ووراوه، کوم بل زېری واوروي، نو لعنت دې ورباندې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_8.mp3', '', 1761754199, 1761754199),
(35138, 'Galatians 1:9', 'Galatians', 1, 9, 'لکه څنګه چې مخکې مې درته وویل، اوس یې یوځل بیا درته وایم: هرڅوک چې بې له هغه زېري نه چې تاسو قبول کړی دی، د کوم بل زېري وعظ درته وکړي، نو لعنت دې وي ورباندې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_9.mp3', '', 1761754199, 1761754199),
(35139, 'Galatians 1:10', 'Galatians', 1, 10, 'ایا زه اوس کوښښ کوم چې انسان راضي وساتم یا خدای؟ که چېرې زما مقصد د خلکو خوشحالول وي، نو د مسیح خدمتګار به نه یم. د پولوس زېری د مسیح له خوا دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_10.mp3', '', 1761754199, 1761754199),
(35140, 'Galatians 1:11', 'Galatians', 1, 11, 'زما خویندو او ورونو! زه غواړم تاسو په دې پوه شئ چې هغه زېری چې ما تاسو ته ووراوه، هغه د انسان له خوا جوړ شوی زېری نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_11.mp3', '', 1761754199, 1761754199),
(35141, 'Galatians 1:12', 'Galatians', 1, 12, 'هغه ما د چا له خوا تر‌لاسه کړی نه دی او نه چا راته زده کړی دی، بلکې خپله عیسی مسیح راته ښکاره کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_12.mp3', '', 1761754199, 1761754199),
(35142, 'Galatians 1:13', 'Galatians', 1, 13, 'تاسو به زما د تېر ژوند په هکله چې کله ما د یهودي دین څخه پیروي کوله، اورېدلې وي چې څنګه په بې‌رحمۍ سره به مې د خدای کلیسا ځوروله او کوښښ به مې کاوه چې هغه له منځه یوسم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_13.mp3', '', 1761754199, 1761754199),
(35143, 'Galatians 1:14', 'Galatians', 1, 14, 'زه په یهودیت کې د خپل قوم د خپلو ډېرو همزولو نه مخکې وم او د خپلو نیکونو په روایتونو باندې ټینګ ولاړ وم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_14.mp3', '', 1761754199, 1761754199),
(35144, 'Galatians 1:15', 'Galatians', 1, 15, 'خو د خدای رضا په دې کې وه چې زه یې د زېږېدلو نه مخکې د مور په ګېډه کې غوره کړم او د خپل فضل په وسیله یې راوبللم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_15.mp3', '', 1761754199, 1761754199),
(35145, 'Galatians 1:16', 'Galatians', 1, 16, 'چې خپل زوی ماته راښکاره کړي، ترڅو غیریهودیانو ته د هغه په هکله زېری ورسوم. په دې کار کې ما د هېڅ انسان سره مشوره نه ده کړې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_16.mp3', '', 1761754199, 1761754199),
(35146, 'Galatians 1:17', 'Galatians', 1, 17, 'او نه اورشلیم ته لاړم، ترڅو د هغو خلکو سره ووینم چې زما نه مخکې رسولان وو، بلکې عربستان ته لاړم او وروسته بېرته دمشق ته راستون شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_17.mp3', '', 1761754199, 1761754199),
(35147, 'Galatians 1:18', 'Galatians', 1, 18, 'درې کاله وروسته اورشلیم ته لاړم، ترڅو د پطروس سره وپېژنم او پنځلس ورځې د هغه سره پاتې شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_18.mp3', '', 1761754199, 1761754199),
(35148, 'Galatians 1:19', 'Galatians', 1, 19, 'خو ما پرته د عیسی مسیح د ورور یعقوب نه نور رسولان ونه لیدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_19.mp3', '', 1761754199, 1761754199),
(35149, 'Galatians 1:20', 'Galatians', 1, 20, 'زه چې تاسو ته څه لیکم هغه رښتیا دي. خدای پوهیږي چې زه دروغ نه وایم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_20.mp3', '', 1761754199, 1761754199),
(35150, 'Galatians 1:21', 'Galatians', 1, 21, 'وروسته بیا د سوریې او قیلیقیې سیمو ته لاړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_21.mp3', '', 1761754199, 1761754199),
(35151, 'Galatians 1:22', 'Galatians', 1, 22, 'په یهودیې کې د مسیح د کلیساګانو غړو زه نه پېژندلم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_22.mp3', '', 1761754199, 1761754199),
(35152, 'Galatians 1:23', 'Galatians', 1, 23, 'هغوی یوازې اورېدلي وو چې خلکو به ویل: «هغه چا چې مونږ به یې ځورولو، اوس د هماغه ایمان په هکله وعظ کوي چې یو وخت یې د هغه د له منځه وړلو کوښښ کاوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_23.mp3', '', 1761754199, 1761754199),
(35153, 'Galatians 1:24', 'Galatians', 1, 24, 'او هغوی زما په خاطر د خدای ثنا وویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians1_verse_24.mp3', '', 1761754199, 1761754199),
(35154, 'Acts 1:1', 'Acts', 1, 1, 'ای تیوفیلوسه! ما په خپل لومړي کتاب کې د هغو کارونو په هکله ولیکل چې عیسی سرته ورسول او تعلیم یې ورکړ، یعنې د هماغې ورځې نه چې کار یې پیل کړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_1.mp3', '', 1761754199, 1761754199),
(35155, 'Acts 1:2', 'Acts', 1, 2, 'تر هغې ورځې پورې چې هغه اسمان ته پورته کړای شو. مخکې له دې چې دا کار وشي هغه خپلو رسولانو ته چې هغه غوره کړي وو د روح القدس په وسیله لارښوونې وکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_2.mp3', '', 1761754199, 1761754199),
(35156, 'Acts 1:3', 'Acts', 1, 3, 'عیسی د خپلې مړینې څخه وروسته خپل ځان رسولانو ته وښود او ډېر ثبوتونه یې وړاندې کړل چې هغه ژوندی دی او تر څلوېښتو ورځو پورې څو څو ځلې هغوی ته ښکاره شو او د هغوی سره یې د خدای د پاچاهۍ په هکله خبرې وکړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_3.mp3', '', 1761754199, 1761754199),
(35157, 'Acts 1:4', 'Acts', 1, 4, 'هغه وخت چې عیسی لا د هغوی سره ؤ، هغوی ته یې حکم وکړ: «د اورشلیم څخه لاړ نه شئ بلکې د هغې وعدې انتظار وباسئ چې زما پلار کړې ده او د هغې په هکله مې تاسو ته ویلي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_4.mp3', '', 1761754199, 1761754199),
(35158, 'Acts 1:5', 'Acts', 1, 5, 'یحیی به په اوبو باندې د تعمید غسل ورکاوه، خو څو ورځې وروسته به تاسو ته په روح القدس د تعمید غسل درکړل شي.» اسمان ته د عیسی مسیح ختل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_5.mp3', '', 1761754199, 1761754199),
(35159, 'Acts 1:6', 'Acts', 1, 6, 'نو کله چې رسولان سره راټول شول، د عیسی څخه یې پوښتنه وکړه: «څښتنه، ایا همدا یې وخت دی چې ته به بیا اسراییلو ته پاچاهي ورکوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts1_verse_6.mp3', '', 1761754199, 1761754199),
