(35198, 'Romans 3:20', 'Romans', 3, 20, 'ځکه چې هېڅوک به هم د شریعت په حکمونو باندې په عمل کولو سره د خدای په نظر کې عادل ونه ګڼل شي. د شریعت کار دا دی چې مونږ ته خپله ګناه راپېژني. د ایمان په وسیله عادل کېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_20.mp3', '', 1761754199, 1761754199),
(35199, 'Romans 3:21', 'Romans', 3, 21, 'اوس خدای مونږ ته هغه لاره ښکاره کړې ده چې د هغې په وسیله بې له دې چې په حکمونو باندې عمل وکړو، د هغه په نظر کې عادل شو لکه څنګه چې شریعت او پیغمبرانو د هغې شاهدي ورکړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_21.mp3', '', 1761754199, 1761754199),
(35200, 'Romans 3:22', 'Romans', 3, 22, 'دا عدالت په عیسی مسیح باندې د ایمان درلودلو له لارې تر‌لاسه کیږي. خدای ټول په عیسی مسیح باندې په ایمان راوړلو سره عادل ګڼي، ځکه چې د یهودیانو او غیریهودیانو ترمنځ هېڅ فرق نشته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_22.mp3', '', 1761754199, 1761754199),
(35201, 'Romans 3:23', 'Romans', 3, 23, 'ځکه چې ټولو ګناه کړې ده او د خدای د جلال نه بې‌برخې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_23.mp3', '', 1761754199, 1761754199),
(35202, 'Romans 3:24', 'Romans', 3, 24, 'خو ټول د خدای په وړیا فضل سره د عیسی مسیح په وسیله چې هغوی یې د خپلو ګناهونو نه خلاص کړي دي، عادل ګڼل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_24.mp3', '', 1761754199, 1761754199),
(35203, 'Romans 3:25', 'Romans', 3, 25, 'خدای مسیح د دې دپاره وټاکه، ترڅو خپله وینه د خلکو د ګناهونو د بخښنې په خاطر چې په هغه باندې په ایمان راوړلو سره تر‌لاسه کیږي، یوه وسیله شي. خدای دا کار د دې دپاره وکړ چې خپل عدالت ښکاره کړي، ځکه چې خدای صابر دی او په تېرو ګناهونو باندې سترګې پټوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_25.mp3', '', 1761754199, 1761754199),
(35204, 'Romans 3:26', 'Romans', 3, 26, 'دا د دې دپاره ؤ چې په دې زمانه کې خپل عدالت ښکاره کړي او دا ثابته کړي چې هغه په خپله عادل دی او هغه څوک عادل جوړوي چې په عیسی مسیح باندې ایمان راوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_26.mp3', '', 1761754199, 1761754199),
(35205, 'Romans 3:27', 'Romans', 3, 27, 'نو بیا مونږ په څه باندې ویاړ وکړو؟ په هېڅ شي باندې نه. ایا په دې دلیل چې په شریعت باندې عمل کوو؟ نه، بلکې د ایمان په وسیله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_27.mp3', '', 1761754199, 1761754199),
(35206, 'Romans 3:28', 'Romans', 3, 28, 'ځکه مونږ پوهېږو چې د ایمان په وسیله عادل ګڼل کېږو، نه په شریعت باندې په عمل کولو سره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_28.mp3', '', 1761754199, 1761754199),
(35207, 'Romans 3:29', 'Romans', 3, 29, 'ایا خدای یوازې د یهودیانو خدای دی؟ ایا هغه د غیریهودیانو خدای هم نه دی؟ بې له شکه چې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_29.mp3', '', 1761754199, 1761754199),
(35208, 'Romans 3:30', 'Romans', 3, 30, 'خدای یو دی او هغه خلک یوازې د ایمان په وسیله عادل جوړوي، که هغه یهودیان دي یا غیریهودیان.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_30.mp3', '', 1761754199, 1761754199),
(35209, 'Romans 3:31', 'Romans', 3, 31, 'ایا د دې معنی دا ده چې مونږ په دې ایمان باندې شریعت ایسته غورځوو؟ نه، هېڅکله نه، بلکې نور هم په هغه باندې ټینګ ودرېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans3_verse_31.mp3', '', 1761754199, 1761754199),
(35210, 'Titus 2:1', 'Titus', 2, 1, 'خو ته هغه تعلیم ورکوه چې د سمې عقیدې له مخې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_1.mp3', '', 1761754199, 1761754199);